import{d as g,C as t,o as h,c as u,j as i,a,E as e,a3 as d}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"中庸·第32章","description":"《中庸》第 32 章——唯天下至诚，为能经纶天下之大经，立天下之大本，知天地之化育；夫焉有所倚？肫肫其仁，渊渊其渊，浩浩其天。","frontmatter":{"title":"中庸·第32章","description":"《中庸》第 32 章——唯天下至诚，为能经纶天下之大经，立天下之大本，知天地之化育；夫焉有所倚？肫肫其仁，渊渊其渊，浩浩其天。","category":"guide","aliases":["第32章","中庸第32章","经纶大经"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-32.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-32.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-32.md"},f=g({...m,setup(p){const r=[{id:"jinglun",label:"唯天下至诚 · 经纶大经，立大本，知天地之化育",showLabel:!0,sentences:[["唯天下至诚，为能",{text:"经纶",glossary:"jinglun"},"天下之大经，立天下之大本，知天地之化育。"]],note:"「唯天下至诚，为能经纶天下之大经，立天下之大本，知天地之化育」——只有天下至诚的人，才能经纶（整理丝缕，引申为经营治理）天下之大纲，树立天下之大本，知晓天地之化育。三句由外而内、由人而天。"},{id:"wuyi",label:"夫焉有所倚 · 肫肫其仁，渊渊其渊，浩浩其天",showLabel:!0,sentences:[["夫",{text:"焉有所倚",glossary:"yanyisuo"},"？",{text:"肫肫",glossary:"zhunzhun"},"其仁！",{text:"渊渊",glossary:"yuanyuan"},"其渊！",{text:"浩浩",glossary:"haohao"},"其天！"]],note:"「夫焉有所倚？」——他何尝有所倚靠？（言至诚者不倚一偏。）「肫肫其仁！渊渊其渊！浩浩其天！」——其仁恳挚（肫肫＝恳切），其深如渊，其大浩荡如天。三句四个叠字，极写至诚之德。"},{id:"shuZhi",label:"苟不固聪明圣知达天德者，其孰能知之",showLabel:!0,sentences:[["苟不",{text:"固",glossary:"gu"},"聪明圣知达天德者，其孰能知之？"]],note:"「苟不固聪明圣知达天德者，其孰能知之？」——若不是「固」（固有、本然）聪明圣智而通达天德的人，谁能真正知晓此至诚之道？此句以反诘收束全章，也回应上节「知天地之化育」之「知」：此道唯至诚者能知。"}],s=[{id:"jinglun",term:"经纶",pinyin:"jīng lún",meaning:"朱注：「经、纶，皆治丝之事。经者，理其绪而分之；纶者，比其类而合之也。」引申为治理。"},{id:"yanyisuo",term:"焉有所倚",pinyin:"yān yǒu suǒ yǐ",meaning:"哪里有所倚靠？朱注：「此皆至诚无妄自然之功用，夫岂有所倚著于物而后能哉。」"},{id:"zhunzhun",term:"肫肫",pinyin:"zhūn zhūn",meaning:"朱注：「肫肫，恳至貌，以经纶而言也。」"},{id:"yuanyuan",term:"渊渊",pinyin:"yuān yuān",meaning:"朱注：「渊渊，静深貌，以立本而言也。」"},{id:"haohao",term:"浩浩",pinyin:"hào hào",meaning:"朱注：「浩浩，广大貌，以知化而言也。」"},{id:"gu",term:"固",pinyin:"gù",meaning:"朱注：「固，犹实也。」郑氏曰：「惟圣人能知圣人也。」"}];return(y,n)=>{const l=t("DaoTextReading"),o=t("DaoKeywordCards");return h(),u("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第32章",tabindex:"-1"},[a("中庸·第32章 "),i("a",{class:"header-anchor",href:"#中庸·第32章","aria-label":'Permalink to "中庸·第32章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[a("第三十二章说「至诚」的三项功用——"),i("strong",null,"经纶天下之大经，立天下之大本，知天地之化育"),a("；一句「夫焉有所倚？」，再以「肫肫其仁！渊渊其渊！浩浩其天！」三叹形容，末句「其孰能知之」。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),e(l,{colophon:"经纶大经 · 立大本 · 肫肫其仁，浩浩其天",tone:"ink",sections:r,glossary:s,"default-mode":"slips","aria-label":"中庸·第32章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),e(o,{items:[{term:"经纶",pinyin:["jīng","lún"],meaning:"朱注：皆治丝之事——「经者，理其绪而分之；纶者，比其类而合之」。治理天下如理丝。"},{term:"大经",pinyin:["dà","jīng"],meaning:"五品之人伦——君臣、父子、夫妇、昆弟、朋友。"},{term:"大本",pinyin:["dà","běn"],meaning:"所性之全体。"},{term:"焉有所倚",pinyin:["yān","yǒu","suǒ","yǐ"],meaning:"哪里有所倚靠？至诚是自然的功用，不倚著于外物。"}]}),e(o,{items:[{term:"肫肫其仁",pinyin:["zhūn","zhūn","qí","rén"],meaning:"肫肫：恳至貌。以经纶而言。"},{term:"渊渊其渊",pinyin:["yuān","yuān","qí","yuān"],meaning:"渊渊：静深貌。以立本而言。"},{term:"浩浩其天",pinyin:["hào","hào","qí","tiān"],meaning:"浩浩：广大貌。以知化而言。三句各应一事。"},{term:"苟不固聪明圣知达天德者",pinyin:["gù","cōng","míng","shèng","zhì"],meaning:"圣读 shèng；知读 zhì。固：实。若不是确实聪明圣智而达天德的人，谁能知道呢？——郑氏：「惟圣人能知圣人也。」"}]}),n[4]||(n[4]=d('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>经纶大经 · 立大本</strong>：只有天下至诚的人，才能经纶天下的大经（人伦），立天下的大本（所性之全体），知道天地的化育。</p><p><strong>夫焉有所倚</strong>：他哪里有所倚靠呢？<strong>肫肫然恳切的仁！渊渊然静深的渊！浩浩然广大的天！</strong></p><p><strong>其孰能知之</strong>：如果不是确实聪明圣智而达于天德的人，谁能知道他呢？</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第三十二章三节：</p><ol><li><strong>三项功用</strong>：经纶天下之大经、立天下之大本、知天地之化育</li><li><strong>无倚的三叹</strong>：夫焉有所倚？肫肫其仁！渊渊其渊！浩浩其天！</li><li><strong>知者其谁</strong>：苟不固聪明圣知达天德者，其孰能知之</li></ol><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「经纶」二字的训解极妙</strong>：朱注说经是「<strong>理其绪而分之</strong>」，纶是「<strong>比其类而合之</strong>」——治天下如理丝：<strong>该分的分，该合的合</strong>。这两个字本身就是一套方法论。</li><li><strong>三项功用是一组</strong>：大经（人伦，横向的关系）→ 大本（性之全体，纵向的根本）→ 知天地之化育（向外的通晓）。<strong>从人事到本性再到天地。</strong></li><li><strong>「夫焉有所倚」是全章的骨头</strong>：至诚的这些话，<strong>不靠依附任何东西</strong>。朱注说这是「自然之功用」。世上的许多「成事」，其实倚着势、倚着人；而至诚不倚。</li><li><strong>三叹与三项一一对应</strong>：肫肫其仁（恳切）对经纶、渊渊其渊（静深）对立本、浩浩其天（广大）对知化。<strong>不是三个形容词，是三件事的样子。</strong></li><li><strong>末句「其孰能知之」是自觉的孤独</strong>：郑氏说「惟圣人能知圣人」。这一句也解释了前面 30、31 章的赞语为何那么重——<strong>那是同类才看得见的</strong>。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用「经纶」二字做事的比照</strong>：这件事里，哪些是「理其绪而分之」，哪些是「比其类而合之」？我是不是只做了其中一半？</li><li><strong>「焉有所倚」</strong>：我手上这件事，去掉所有外部依靠之后，还成立吗？</li><li><strong>三叹当境界的标尺</strong>：恳切够不够？静深够不够？广大够不够？</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>只有天下至诚的人，才能<strong>把天下的人伦理出来</strong>，<strong>把性之本立起来</strong>，<strong>通晓天地的化育</strong>。</p><p>而他<strong>不靠什么可倚之物</strong>——那是：<strong>肫肫然恳切的仁，渊渊然静深的渊，浩浩然广大的天。</strong></p><p>这样的人，若不是同样确实聪明圣智、达于天德的人，谁能知道他呢？</p><p>这一章最实在的启示在「经纶」二字：<strong>治丝之法，一在分，一在合。</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「经者，理其绪而分之；纶者，比其类而合之」——我做的事里，哪一半没做？</li><li>「夫焉有所倚」——去掉所有外部依靠，我手上的事还成立吗？</li><li>「肫肫其仁／渊渊其渊／浩浩其天」——恳切、静深、广大，我够哪一样？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-31">中庸·第31章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-33">中庸·第33章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',24))])}}});export{b as __pageData,f as default};
